import{Z as e,e as o,f as i,a0 as a}from"./chunks/framework.DmpHOl9T.js";const c=JSON.parse('{"title":"Submissions & Workflows","description":"","frontmatter":{},"headers":[],"relativePath":"guides/submissions-workflows/index.md","filePath":"guides/submissions-workflows/index.md","lastUpdated":1787061592000}'),n={name:"guides/submissions-workflows/index.md"};function t(r,s,d,u,l,m){return o(),i("div",null,[...s[0]||(s[0]=[a('<h1 id="submissions-workflows" tabindex="-1">Submissions &amp; Workflows <a class="header-anchor" href="#submissions-workflows" aria-label="Permalink to &quot;Submissions &amp; Workflows&quot;">​</a></h1><p>Submission lifecycle, statuses, screening, reports, and rendering stored content.</p><h2 id="editing-submissions-on-the-front-end" tabindex="-1"><a href="/guides/submissions-workflows/editing-submissions-on-the-front-end">Editing Submissions on the Front End</a> <a class="header-anchor" href="#editing-submissions-on-the-front-end" aria-label="Permalink to &quot;[Editing Submissions on the Front End](/guides/submissions-workflows/editing-submissions-on-the-front-end)&quot;">​</a></h2><p>Formie can render a saved submission back into the form so someone can update it from the front end — account areas, application review flows, or any case where data may change after first submit.</p><h2 id="relations-between-submissions-and-entries" tabindex="-1"><a href="/guides/submissions-workflows/relations-between-submissions-and-entries">Relations Between Submissions and Entries</a> <a class="header-anchor" href="#relations-between-submissions-and-entries" aria-label="Permalink to &quot;[Relations Between Submissions and Entries](/guides/submissions-workflows/relations-between-submissions-and-entries)&quot;">​</a></h2><p>Submissions can be related to Craft elements — entries, categories, products, users — so form data stays connected to the content it belongs to. Relations are set in Twig before render, not chosen manually by editors in the form builder.</p><h2 id="saved-reports-and-scheduled-delivery" tabindex="-1"><a href="/guides/submissions-workflows/saved-reports-and-scheduled-delivery">Saved Reports and Scheduled Delivery</a> <a class="header-anchor" href="#saved-reports-and-scheduled-delivery" aria-label="Permalink to &quot;[Saved Reports and Scheduled Delivery](/guides/submissions-workflows/saved-reports-and-scheduled-delivery)&quot;">​</a></h2><p>Getting-started walkthrough for saved reports and scheduled email delivery — links to the reports reference for formats, permissions, cron, and troubleshooting.</p><h2 id="run-custom-code-on-page-submit-or-form-submit" tabindex="-1"><a href="/guides/submissions-workflows/run-custom-code-on-page-submit-or-form-submit">Run Custom Code on Page Submit or Form Submit</a> <a class="header-anchor" href="#run-custom-code-on-page-submit-or-form-submit" aria-label="Permalink to &quot;[Run Custom Code on Page Submit or Form Submit](/guides/submissions-workflows/run-custom-code-on-page-submit-or-form-submit)&quot;">​</a></h2><p>Every page POST uses the same pipeline. This guide shows the two public hooks — after a page submit, and when the form is submitted — without <code>afterTask</code> archaeology.</p><h2 id="submission-screening-rules-in-practice" tabindex="-1"><a href="/guides/submissions-workflows/submission-screening-rules-in-practice">Submission Screening Rules in Practice</a> <a class="header-anchor" href="#submission-screening-rules-in-practice" aria-label="Permalink to &quot;[Submission Screening Rules in Practice](/guides/submissions-workflows/submission-screening-rules-in-practice)&quot;">​</a></h2><p>Submission screening is Formie&#39;s unified layer for deciding whether a submission is legitimate before it is saved and dispatched. This guide shows how guards, captchas, and content rules work together in practice — and how to tune them without blocking real users.</p><h2 id="submission-statuses-and-conditional-workflows" tabindex="-1"><a href="/guides/submissions-workflows/submission-statuses-and-conditional-workflows">Submission Statuses and Conditional Workflows</a> <a class="header-anchor" href="#submission-statuses-and-conditional-workflows" aria-label="Permalink to &quot;[Submission Statuses and Conditional Workflows](/guides/submissions-workflows/submission-statuses-and-conditional-workflows)&quot;">​</a></h2><p>Submission <strong>statuses</strong> are team workflow labels on saved submissions. <strong>Conditions</strong> change what the form shows and which notifications send based on answers. Together they let you route work after submit and tailor the form experience before submit.</p><h2 id="submission-workflow-and-stages-explained" tabindex="-1"><a href="/guides/submissions-workflows/submission-workflow-and-stages-explained">Submission Workflow and Stages Explained</a> <a class="header-anchor" href="#submission-workflow-and-stages-explained" aria-label="Permalink to &quot;[Submission Workflow and Stages Explained](/guides/submissions-workflows/submission-workflow-and-stages-explained)&quot;">​</a></h2><p>Formie runs every submission through a staged pipeline. This guide explains what each stage does, which requests run the full flow, and how to think about hooks before you write PHP.</p><h2 id="using-submission-workflow-events" tabindex="-1"><a href="/guides/submissions-workflows/using-submission-workflow-events">Using Submission Workflow Events</a> <a class="header-anchor" href="#using-submission-workflow-events" aria-label="Permalink to &quot;[Using Submission Workflow Events](/guides/submissions-workflows/using-submission-workflow-events)&quot;">​</a></h2><p>Most extensions only need workflow event listeners — validation tweaks, post-save sync, blocking dispatch on test forms — without custom task or stage classes. This walkthrough wires the common patterns from a Craft module.</p><h2 id="adding-a-custom-workflow-task-from-scratch" tabindex="-1"><a href="/guides/submissions-workflows/adding-a-custom-workflow-task-from-scratch">Adding a Custom Workflow Task from Scratch</a> <a class="header-anchor" href="#adding-a-custom-workflow-task-from-scratch" aria-label="Permalink to &quot;[Adding a Custom Workflow Task from Scratch](/guides/submissions-workflows/adding-a-custom-workflow-task-from-scratch)&quot;">​</a></h2><p>When one ordered step inside an existing stage is what you need — before integrations, after spam checks, and so on — register a custom task and insert it relative to a built-in anchor. This walkthrough queues an internal review job before CRM dispatch.</p><h2 id="adding-a-custom-workflow-stage-from-scratch" tabindex="-1"><a href="/guides/submissions-workflows/adding-a-custom-workflow-stage-from-scratch">Adding a Custom Workflow Stage from Scratch</a> <a class="header-anchor" href="#adding-a-custom-workflow-stage-from-scratch" aria-label="Permalink to &quot;[Adding a Custom Workflow Stage from Scratch](/guides/submissions-workflows/adding-a-custom-workflow-stage-from-scratch)&quot;">​</a></h2><p>When you need a new phase in the pipeline — not just another task inside <code>screen</code> or <code>dispatch</code> — register a custom stage. This walkthrough adds a fraud score check after spam screening and before authorisation.</p><h2 id="save-and-continue-later" tabindex="-1"><a href="/guides/submissions-workflows/save-and-continue-later">Save and Continue Later</a> <a class="header-anchor" href="#save-and-continue-later" aria-label="Permalink to &quot;[Save and Continue Later](/guides/submissions-workflows/save-and-continue-later)&quot;">​</a></h2><p>Long and multi-page forms lose completions when visitors get interrupted. Formie stores incomplete submissions in the database, optionally exposes a save button with resume links, and can restore in-progress state automatically when someone returns. This walkthrough configures the feature end-to-end for a job application or registration form.</p>',24)])])}const f=e(n,[["render",t]]);export{c as __pageData,f as default};
